var SITE_IDS = ["claude", "chatgpt", "grok", "gemini", "copilot", "mscopilot", "local"]

// Two custom-address settings: none, and one for every site.
var CUSTOM = {
    none: undefined,
    set: {
        claude: "https://claude.example.org/c",
        chatgpt: "https://chat.example.net/",
        grok: "https://grok.example.com:8443/",
        gemini: "https://gemini.example.com/",
        copilot: "https://git.example.com/",
        mscopilot: "https://copilot.example.com/",
        local: "http://127.0.0.1:8080/x"
    }
}

// One compact line of answers for a site, address and custom setting:
// nav (not clicked), nav (clicked), nav as subframe, classifySubframe,
// new window (clicked dialog, clicked, script dialog, script), isPageUrl,
// offSiteHost, localOwnerPort. userSites is passed on every request (it is
// ignored by code that predates it).
function row(ChatSites, siteId, url, customUrls, userSites) {
    var base = function (extra) {
        var request = { siteId: siteId, url: url, customUrls: customUrls, userSites: userSites }
        for (var key in extra)
            request[key] = extra[key]
        return request
    }
    var win = function (dialog, clicked) {
        return ChatSites.classifyNewWindow(base({ isDialog: dialog, userInitiated: clicked }))
    }
    var off = ChatSites.offSiteHost(base({}))
    var site = ChatSites.effectiveSite(siteId, customUrls, userSites)
    return [
        ChatSites.classifyNavigation(base({ isMainFrame: true, linkClicked: false })),
        ChatSites.classifyNavigation(base({ isMainFrame: true, linkClicked: true })),
        ChatSites.classifyNavigation(base({ isMainFrame: false, linkClicked: true })),
        ChatSites.classifySubframe(base({})),
        win(true, true), win(false, true), win(true, false), win(false, false),
        ChatSites.isPageUrl(site, url) ? "page" : "no-page",
        (off.off ? "off:" : "on:") + off.host,
        String(ChatSites.localOwnerPort(base({ isMainFrame: true })))
    ].join(" ")
}

function table(ChatSites, userSites) {
    var result = {}
    for (var customKey in CUSTOM) {
        for (var s = 0; s < SITE_IDS.length; s++) {
            for (var a = 0; a < ADDRESSES.length; a++) {
                var key = SITE_IDS[s] + " " + customKey + " " + ADDRESSES[a]
                result[key] = row(ChatSites, SITE_IDS[s], ADDRESSES[a], CUSTOM[customKey], userSites)
            }
        }
    }
    return result
}

